create table raffle_upload (
    id                 number
        generated by default on null as identity
    not null enable,
    file_name          varchar2(4000 char),
    mime_type          varchar2(4000 char),
    object_storage_url varchar2(4000 char),
    created            date not null enable,
    created_by         varchar2(255 char) not null enable,
    updated            date not null enable,
    updated_by         varchar2(255 char) not null enable,
    status             varchar2(50 byte) default 'Pending Approval',
    doc_ai_json        clob
);

alter table raffle_upload
    add constraint inv_upload_id_pk primary key ( id )
        using index enable;


